WITH valid AS (SELECT id, product_name, category, brand, price, cost, stock_qty, launch_date, tags, supplier_id, UPPER(product_name) AS product_name_upper FROM products WHERE launch_date > DATE '2023-02-21' AND supplier_id IS NOT NULL) SELECT id, category, brand, cost, stock_qty, launch_date, tags, product_name_upper, SUM(price) OVER (PARTITION BY category ORDER BY price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_price, SUM(stock_qty) OVER (ORDER BY price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_stock_qty, CUME_DIST() OVER (PARTITION BY supplier_id ORDER BY price DESC) AS price_cume_dist, AVG(cost) OVER (PARTITION BY category ORDER BY price, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS cost_avg_3 FROM valid;
